package project.init.account.domain.entity;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.persistence.PrePersist;import jakarta.persistence.Table;import lombok.AllArgsConstructor;import lombok.Builder;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import project.init.framework.utils.DateTimeUtils;import java.io.Serial;import java.io.Serializable;import java.time.Instant;@Entity@Getter@Setter@Builder@NoArgsConstructor@AllArgsConstructor@Table(name = "role")public class Role implements Serializable {    @Serial    private static final long serialVersionUID = 1L;    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Integer id;    @Column(name = "code", length = 50, nullable = false, unique = true)    private String code;    @Column(name = "description", columnDefinition = "TEXT")    private String description;    @Column(name = "created_at", updatable = false)    private Instant createdAt;    @PrePersist    protected void onCreate() {        createdAt = DateTimeUtils.getCurrentTimeUTC();    }}